local UIFishPoolContestRewardsPopupNode = "Game.UI.Fishing.FishPoolContestRewardsPopup.UIFishPoolContestRewardsPopupNode"
local fishingComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.FishingComponent)

function UIFishPoolContestRewardsPopupDialog:__init() 
    self._fishPlaceId = nil                --渔场id
    self._activityId = nil                 --活动id
    self._data = {}
end

function UIFishPoolContestRewardsPopupDialog:__delete()
    self._fishPlaceId = nil                --排行榜数据
    self._activityId = nil                 --活动id
    self._data = nil
end

function UIFishPoolContestRewardsPopupDialog:Awake()
    local argument = self.controller.Argument.parameters
    if not argument then
        return
    end
    self._fishPlaceId = checkNumber(argument.fishPlaceId)    
    self._activityId = FishingUtils.GetFishPlaceActivityId(self._fishPlaceId, ConstantsFishing.ActivityType.Summer)
    if self._activityId == 0 then
        return
    end

    self:InitData()
    self:FillSelf()
end

function UIFishPoolContestRewardsPopupDialog:InitData()
    local t = FishingUtils.GetAllIntegralReward(self._activityId)


    for i = 1, #t do
        for j = i + 1, #t do
            local a = t[i]
            local b = t[j]
            local isDrawA = FishingUtils.IsDrawIntegralReward(self._fishPlaceId, a)
            local isDrawB = FishingUtils.IsDrawIntegralReward(self._fishPlaceId, b)
            local isTrue = false
            if isDrawA then
                if isDrawB then 
                    isTrue = checkNumber(a) > checkNumber(b)
                else
                    isTrue = true
                end
            else
                isTrue = checkNumber(a) > checkNumber(b)
            end

            if isTrue then
                local id = a
                t[i] = b
                t[j] = id
            end
        end
    end

    self._data = t
end

function UIFishPoolContestRewardsPopupDialog:FillSelf()
    SetButtonAction(self.FontStyleButton, Bind(self, self.OnDrawReward))
    self.ListContent:InitListView(#self._data, Bind(self, self.OnGetCellByIndex))
end

function UIFishPoolContestRewardsPopupDialog:OnGetCellByIndex(listView, index)
    if index < 0 then
        return nil
    end

    local id = self._data[index + 1]
    local cell = listView:NewListViewItem("Cell") 
    local scr = CfUtils.GetLuaScr(cell.gameObject, UIFishPoolContestRewardsPopupNode)
    if scr then
        local data = FishingUtils.GetFishIntegralRewardVo(id)
        scr:Refresh(data, self._fishPlaceId)
    end

    return cell
end

function UIFishPoolContestRewardsPopupDialog:OnDrawReward()
    local t = FishingUtils.GetAllCanDrawIntegralRewardId(self._fishPlaceId)
    if not t or table.count(t) <= 0 then
        GameUtils.Toast(localize("当前无奖励可领取"))
        return
    end

    fishingComponent:FishingReceiveScoreRewardsReq(self._fishPlaceId, self._data.id, function()
        GameUtils.ReloadData(self.ListContent, #self._data)
    end)
end

